mapper.insert:
insert into sys_notice (
    notice_title, notice_type, notice_content, status, audience, remark, create_by, create_time
)
select #{title}, '2', #{content}, '0', 'ADMIN', #{dedupKey}, 'system', sysdate()
from dual
where not exists (
    select 1 from sys_notice where audience = 'ADMIN' and remark = #{dedupKey}
)
